INSERT INTO `candidates` VALUES (20,1,'Balija Sravani','balijasravani25@gmail.com','9704312508','resumes/f86c5d0c6059439b882b550a7ed0c190.pdf','{\"email\": \"balijasravani25@gmail.com\", \"phone\": \"9704312508\", \"skills\": [\"Python\", \"HTML\", \"CSS\", \"Javascript\", \"Bootstrap\", \"MySQL\", \"Java\", \"Data Mining\", \"Classification Techniques\", \"Database Management\", \"Fraud Detection Techniques\"], \"summary\": \"Recent Computer Science graduate with strong knowledge of programming, web development, and databases. Experienced in Python and full-stack Web development through academic projects and internship experience. Passionate about solving real-world problems through technology and seeking an opportunity as a Software Engineer to learn, grow, and contribute to a dynamic development team.\", \"location\": null, \"projects\": [{\"name\": \"Implementation of Data Mining Techniques In Upcoding Fraud Detection in the Monetary Domains\", \"description\": \"Developed to detect fraudulent claims using data mining and classification techniques. Designed user modules and implemented the system using Java and MySQL. Gained practical experience in fraud detection, data analysis, & real-time application development.\", \"technologies\": [\"Java\", \"MySQL\", \"Data Mining\", \"Classification Techniques\", \"Database Management\", \"Fraud Detection Techniques\"]}], \"education\": [{\"year\": 2025, \"degree\": \"MCA\", \"percentage\": \"76%\", \"institution\": \"Sri Vani Institute Of Management & Sciences, Anantapur\"}, {\"year\": 2023, \"degree\": \"Degree\", \"percentage\": \"79%\", \"institution\": \"Government College (Autonomous), Anantapur\"}, {\"year\": 2020, \"degree\": \"Xll Grade\", \"percentage\": \"53%\", \"institution\": \"Sri Sathya Sai Art’s & Science junior College For Women, Anantapur\"}, {\"year\": 2018, \"degree\": \"X Grade\", \"percentage\": \"93%\", \"institution\": \"ZP High School Tapovannagar, Anantapur\"}], \"full_name\": \"Balija Sravani\", \"experience\": [], \"certifications\": [{\"name\": \"MongoDB: The complete guide to NoSQL database development\", \"year\": 2026, \"platform\": \"Coursera\"}, {\"name\": \"Microsoft Azure\", \"year\": 2026, \"platform\": \"Coursera\"}, {\"name\": \"Data Analytics\", \"year\": 2025, \"platform\": null}]}','{\"email\": \"balijasravani25@gmail.com\", \"phone\": \"9704312508\", \"full_name\": \"Balija Sravani\"}','Selected','2026-11-14 15:59:38','Not Started',NULL,NULL,NULL),(21,1,'AKSHAY KUMAR','jujareakshaykumar@gmail.com','+91 7386177162','resumes/d4e6b08af69c468c8bd9aabc01c5b4b5.docx','{\"email\": \"jujareakshaykumar@gmail.com\", \"phone\": \"+91 7386177162\", \"skills\": [\"Python\", \"SQL\", \"MySQL\", \"Windows 10/11\", \"Microsoft Excel\", \"Microsoft Word\", \"Microsoft PowerPoint\", \"Power BI\", \"Zoho CRM\", \"Hardware troubleshooting\", \"Software troubleshooting\", \"Ticket management\", \"Remote support\", \"Computer hardware components\", \"OS fundamentals\", \"Software installation\", \"Software configuration\", \"Software updates\", \"Networking basics\", \"TCP/IP\", \"Wi-Fi\", \"Connectivity troubleshooting\", \"File/folder permissions\", \"Access management\", \"Microsoft Office suite troubleshooting\", \"Virus/malware awareness\", \"Basic system security\", \"Customer support fundamentals\", \"Ticketing concepts\", \"Communication\", \"Customer Service Orientation\", \"Analytical Thinking\", \"Problem Solving\", \"Documentation\", \"Process Improvement\", \"Team Collaboration\", \"Adaptability\", \"Time Management\", \"Quick Learning\", \"Comfortable in fast-paced, cross-functional environments\"], \"summary\": \"B.Sc. Computer Science graduate with a broad technical foundation spanning programming, databases, business applications, and IT support. Comfortable moving across the IT stack — from troubleshooting and system support to data analysis, reporting, and CRM/business-process configuration. Strong analytical thinking, documentation habits, and a fast learning curve on new tools and technologies. Seeking an entry-level opportunity in the IT industry — Software Support, Service Desk, Data Analytics, Business/CRM Applications, or Junior Development — where these skills can grow into a long-term technology career.\", \"location\": \"Andhra Pradesh, India\", \"projects\": [{\"name\": \"Sales Data Analysis using Python\", \"tools\": [\"Python\", \"Pandas\", \"NumPy\", \"Matplotlib\"], \"description\": \"Cleaned and analyzed sales datasets using Python and Pandas. Generated insights using Pandas and NumPy. Visualized trends using Matplotlib for business reporting.\"}, {\"name\": \"Zoho CRM Sales Process Simulation\", \"tools\": [\"Zoho CRM\"], \"description\": \"Created and managed Leads, Contacts, Accounts, and Deals end-to-end. Configured sales stages, workflows, and automation rules. Prepared quotations, sales orders, and invoices. Documented CRM lifecycle and business-process scenarios.\"}], \"education\": [{\"cgpa\": 7.86, \"field\": \"Computer Science with Electronic\", \"degree\": \"Bachelor of Science\", \"end_year\": 2026, \"percentage\": null, \"start_year\": 2023}, {\"cgpa\": null, \"field\": \"Class XII\", \"degree\": \"Intermediate\", \"end_year\": null, \"percentage\": 8.35, \"start_year\": null}, {\"cgpa\": null, \"field\": \"Class X\", \"degree\": \"Secondary School\", \"end_year\": null, \"percentage\": 9.7, \"start_year\": null}], \"full_name\": \"AKSHAY KUMAR\", \"experience\": [], \"certifications\": [\"Python Programming\", \"SQL Fundamentals\", \"Microsoft Excel\", \"Data Analytics (Learning)\", \"Zoho CRM\"]}','{\"email\": \"jujareakshaykumar@gmail.com\", \"phone\": \"+91 7386177162\", \"full_name\": \"AKSHAY KUMAR\"}','On Hold','2026-11-14 16:02:20','Not Started',NULL,NULL,'Selected'),(23,1,'Raketla Mahesh Babu','maheshbabu.raketla@gmail.com','7981604031','resumes/11d2a1767e454a16b14709d3bf3d2a3c.docx','{\"email\": \"maheshbabu.raketla@gmail.com\", \"phone\": \"7981604031\", \"skills\": [\"Python\", \"HTML\", \"CSS\", \"Javascript\", \"Bootstrap\", \"MySQL\", \"Deluge\", \"Client script\"], \"summary\": \"Computer Science graduate with a strong foundation in programming and software development. Skilled in Python, full-stack web development, and database management, with hands-on experience gained through intern and academic projects. Eager to contribute as a Software Engineer in a collaborative, dynamic environment, applying technical skills to build innovative, real-world solutions.\", \"location\": null, \"projects\": [{\"name\": \"Health Insurance Claims Processing Simulator\", \"year\": 2026, \"description\": \"In real time health insurance working process from policy holders request to insurance admin amount paid. It’s a role based ,policyholder,claims Officer,Hospital, Administrator\", \"technologies\": [\"python\", \"Mysql\", \"Flask\"]}, {\"name\": \"AI based code error Explaining using Gemini Model\", \"year\": 2025, \"description\": \"Its is a Group Project,in real-time it is used to explain error in simple english . Its explain code error clearly and if can’t understand it debug automatically and its used to beginners and junior developers who interested to learn code. Gained knowledge understanding of how technology can be used for real-time application.\", \"technologies\": [\"Python\", \"Mysql\", \"Django\"]}], \"education\": [{\"year\": 2026, \"degree\": \"BTech\", \"percentage\": \"75%\", \"institution\": \"Gates institute of technology ,JNTUA\"}, {\"year\": 2022, \"degree\": \"Xll Grade\", \"percentage\": \"78%\", \"institution\": \"Sri Chaitanya jr college\"}, {\"year\": 2020, \"degree\": \"X Grade\", \"percentage\": \"83%\", \"institution\": \"Vignan Em High School\"}], \"full_name\": \"Raketla Mahesh Babu\", \"experience\": [], \"certifications\": [{\"name\": \"MongoDB: The complete guide to NoSQL database development\", \"year\": 2026, \"provider\": \"coursera\"}, {\"name\": \"Microsoft Azure\", \"year\": 2026, \"provider\": \"coursera\"}, {\"name\": \"Cloud Computing Certificate\", \"year\": 2026, \"provider\": \"NPTEL\"}, {\"name\": \"Full-Stack Development\", \"year\": 2025, \"provider\": \"SmartBridge\"}, {\"name\": \"HTML, CSS and JavaScript for Web Developers\", \"year\": 2023, \"provider\": \"Coursera\"}]}','{\"email\": \"maheshbabu.raketla@gmail.com\", \"phone\": \"7981604031\", \"full_name\": \"Raketla Mahesh Babu\"}','Deleted','2026-11-16 07:03:03','Not Started',NULL,NULL,NULL),(24,1,'Raketla Mahesh Babu','raketlamaheshbabu79@gmail.com','7981604031','resumes/20c9e797c4574b42ad3f75d7712ed481.docx','{\"email\": \"Raketlamaheshbabu79@gmail.com\", \"phone\": \"7981604031\", \"skills\": [\"Python\", \"HTML\", \"CSS\", \"Javascript\", \"Bootstrap\", \"MySQL\", \"ZohoCrm\", \"Deluge\", \"ClientScript\"], \"summary\": \"Computer Science graduate with a strong foundation in programming and software development. Skilled in Python, full-stack web development, and database management, Zoho crm with hands-on experience gained through intern and academic projects. Eager to contribute as a Software Engineer in a collaborative, dynamic environment, applying technical skills to build innovative, real-world solutions.\", \"location\": null, \"projects\": [{\"name\": \"Referral Management System\", \"year\": 2026, \"description\": \"Developed a role-based referral system with two roles: R1 (Existing Customers) and R2 (Vendors). Enabled users to refer potential buyers and earn commissions after successful deal closure. Implemented tier-based commission calculation based on deal amount and user tier.\", \"technologies\": [\"zohocrm\", \"clientscript\", \"deluge\"]}, {\"name\": \"Real-Estate Management System\", \"year\": 2026, \"description\": \"Developed a real estate management solution using Zoho CRM to manage property listings, leads, and customer information. Automated business workflows and data management using Deluge scripting. Implemented Client Scripts for field validation, dynamic fo