INSERT INTO `interviews` VALUES (9,20,2,'2026-11-14 21:31:00','Completed','good performer','{\"summary\": \"Candidate is a good performer.\", \"strengths\": [\"Good performance.\"], \"uncertainties\": [], \"additional_notes\": \"\", \"follow_up_questions\": []}','2026-11-14 16:01:19',20,8,13,41,'2026-11-14 16:18:35','Puthaparthi,vasavi nivas,Mitraz',NULL),(10,21,3,'2026-11-14 21:35:00','Completed','good explanation','{\"summary\": \"Candidate provided a good explanation.\", \"strengths\": [\"Good explanation\"], \"uncertainties\": [], \"additional_notes\": \"\", \"follow_up_questions\": []}','2026-11-14 16:06:01',23,7,13,43,'2026-11-14 16:11:49','Puthaparthi,vasavi nivas,Mitraz',NULL),(12,24,2,'2026-11-16 12:35:00','Completed','excellent','{\"summary\": \"Candidate performed excellently.\", \"strengths\": [\"Excellent performance.\"], \"uncertainties\": [], \"additional_notes\": \"\", \"follow_up_questions\": []}','2026-11-16 07:05:19',23,8,13,44,'2026-11-16 07:06:31','Puthaparthi,vasavi nivas,Mitraz',NULL),(13,26,3,'2026-11-20 18:00:00','Completed','Good in technical and not bad confidence and better communication areas to improve techincal','\"INTERVIEW SUMMARY  \\r\\nThe candidate shows strong technical abilities and a reasonable level of confidence. Communication skills were identified as an area that could benefit from improvement.\\r\\n\\r\\nTECHNICAL KNOWLEDGE  \\r\\nGood technical knowledge.\\r\\n\\r\\nSTRENGTHS  \\r\\n- Solid technical competence  \\r\\n- Reasonable confidence\\r\\n\\r\\nAREAS FOR IMPROVEMENT  \\r\\n- Communication skills, particularly in conveying technical concepts\\r\\n\\r\\nFOLLOW-UP POINTS  \\r\\n- Discuss specific technical projects or experiences to further assess depth of knowledge  \\r\\n- Clarify expectations for communication in team settings\\r\\n\\r\\nADDITIONAL NOTES  \\r\\nNot mentioned in the interview notes.\"','2026-11-16 10:30:23',14,7,8,29,'2026-11-17 05:56:55','Our Office MITRAz Foundation :First Floor, Vasawi Niwas Shopping Complex, Gopurum Main Road, near SBI, Puttaparthi, Andhra Pradesh- 515134','1. Documents to carry\r\n1. Updated resume – 2 or 3 copies.\r\n2. Government ID proof (Aadhaar/PAN).\r\n3. Educational certificates.\r\n4. Passport-size photographs.\r\n5. Internship or experience certificates, if available.\r\n6. Project details and certificates.\r\n2. Personal preparation\r\n1. Wear formal clothes.\r\n2. Maintain a neat hairstyle and appearance.\r\n3. Reach the interview location 20–30 minutes early.\r\n4. Keep your phone on silent mode.\r\n5. Carry a notebook and pen.\r\n6. Research the company before attending.\r\n3. Technical preparation\r\n1. Revise your programming fundamentals.\r\n2. Prepare your projects and explain your contribution.\r\n3. Practise basic coding questions.\r\n4. Revise SQL queries and database concepts.\r\n5. Prepare for technical and HR questions.\r\n4. Professional behaviour\r\n1. Greet the interviewer politely.\r\n2. Ask permission before entering.\r\n3. Maintain eye contact.\r\n4. Listen carefully before answering.\r\n5. Be honest if you don\'t know an answer.\r\n6. Thank the interviewer before leaving.\r\n5. Things to check before travelling\r\n- Interview date and time.\r\n- Exact company address.\r\n- Interviewer\'s contact number.\r\n- Parking or transportation availability.\r\n- Whether food or accommodation is provided, if travelling far.\r\n- Whether any original certificates are required.'),(14,27,3,'2026-11-20 18:00:00','Scheduled','',NULL,'2026-11-16 10:55:37',NULL,NULL,NULL,NULL,NULL,'Our Office MITRAz Foundation :First Floor, Vasawi Niwas Shopping Complex, Gopurum Main Road, near SBI, Puttaparthi, Andhra Pradesh- 515134','1. Documents to carry\r\n1. Updated resume – 2 or 3 copies.\r\n2. Government ID proof (Aadhaar/PAN).\r\n3. Educational certificates.\r\n4. Passport-size photographs.\r\n5. Internship or experience certificates, if available.\r\n6. Project details and certificates.\r\n2. Personal preparation\r\n1. Wear formal clothes.\r\n2. Maintain a neat hairstyle and appearance.\r\n3. Reach the interview location 20–30 minutes early.\r\n4. Keep your phone on silent mode.\r\n5. Carry a notebook and pen.\r\n6. Research the company before attending.\r\n3. Technical preparation\r\n1. Revise your programming fundamentals.\r\n2. Prepare your projects and explain your contribution.\r\n3. Practise basic coding questions.\r\n4. Revise SQL queries and database concepts.\r\n5. Prepare for technical and HR questions.\r\n4. Professional behaviour\r\n1. Greet the interviewer politely.\r\n2. Ask permission before entering.\r\n3. Maintain eye contact.\r\n4. Listen carefully before answering.\r\n5. Be honest if you don\'t know an answer.\r\n6. Thank the interviewer before leaving.\r\n5. Things to check before travelling\r\n- Interview date and time.\r\n- Exact company address.\r\n- Interviewer\'s contact number.\r\n- Parking or transportation availability.\r\n- Whether food or accommodation is provided, if travelling far.\r\n- Whether any original certificates are required.'),(15,29,2,'2026-11-17 17:07:00','Scheduled','excellent','\"INTERVIEW SUMMARY  \\r\\n- Candidate was described as excellent.\\r\\n\\r\\nTECHNICAL KNOWLEDGE  \\r\\nNot mentioned in the interview notes.\\r\\n\\r\\nSTRENGTHS  \\r\\nNot mentioned in the interview notes.\\r\\n\\r\\nAREAS FOR IMPROVEMENT  \\r\\nNot mentioned in the interview notes.\\r\\n\\r\\nFOLLOW-UP POINTS  \\r\\nNot mentioned in the interview notes.\\r\\n\\r\\nADDITIONAL NOTES  \\r\\nNot mentioned in the interview notes.\"','2026-11-17 11:38:14',NULL,NULL,NULL,NULL,NULL,'Our Office MITRAz Foundation :First Floor, Vasawi Niwas Shopping Complex, Gopurum Main Road, near SBI, Puttaparthi, Andhra Pradesh- 515134','come with resume');
