INSERT INTO `question_packs` VALUES (10,21,'[{\"topic\": \"Backend frameworks\", \"question\": \"Explain the difference between Flask and Django in terms of project structure and use cases.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Discussion of routing, middleware, ORM, templating, scalability, and when to choose each framework.\"}, {\"topic\": \"REST API\", \"question\": \"How would you design a RESTful API endpoint for creating a new user?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of HTTP POST, status codes, input validation, serialization, error handling, and authentication considerations.\"}, {\"topic\": \"Front-end development\", \"question\": \"Describe how you would implement a responsive navigation bar using Bootstrap.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of Bootstrap navbar classes, grid system, collapse behavior, accessibility attributes, and custom styling.\"}, {\"topic\": \"Database management\", \"question\": \"Write a MySQL query to retrieve all orders for a customer with id 5, including order date and total amount.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"SELECT statement with JOINs, aggregation, GROUP BY, and proper use of aliases.\"}, {\"topic\": \"Python fundamentals\", \"question\": \"What is the purpose of virtual environments in Python, and how do you create one?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Explanation of isolation, dependency management, venv or virtualenv commands, and activation/deactivation steps.\"}, {\"topic\": \"Version control\", \"question\": \"Explain how you would use Git to manage feature branches and merge them into main.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Branching strategy, pull requests, rebase vs merge, conflict resolution, and best practices for code reviews.\"}]','2026-11-14 16:09:51'),(11,20,'[{\"topic\": \"Flask architecture\", \"question\": \"Explain how you would structure a Flask application for a small e-commerce site.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"App factory pattern, blueprints, configuration files, database integration with SQLAlchemy, error handling, deployment considerations.\"}, {\"topic\": \"Django authentication\", \"question\": \"How would you implement user authentication in Django?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Built-in auth system, User model, password hashing, login/logout views, session management, permission checks.\"}, {\"topic\": \"MySQL queries\", \"question\": \"Write a MySQL query to retrieve all orders placed by a customer with id 5, including order date and total amount.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"SELECT statement with JOIN on orders and customers, WHERE clause, aggregation for total amount, proper use of aliases.\"}, {\"topic\": \"Bootstrap\", \"question\": \"Describe how you would create a responsive navigation bar using Bootstrap 5.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Navbar component, responsive classes, collapse behavior, use of container, nav-link styling, accessibility attributes.\"}, {\"topic\": \"REST API\", \"question\": \"What is a RESTful API and how would you design one for a blog platform?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Definition of REST, CRUD endpoints, HTTP verbs, status codes, resource URLs, serialization with JSON, authentication strategy.\"}, {\"topic\": \"Python fundamentals\", \"question\": \"Explain the difference between a list and a tuple in Python.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Mutability, use cases, performance implications, memory usage, methods available on each type.\"}]','2026-11-14 16:17:49'),(12,24,'[{\"topic\": \"Python OOP & Flask\", \"question\": \"Can you explain how Python\'s object-oriented programming features are used in building a Flask application?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Understanding of classes, inheritance, encapsulation in context of Flask views, blueprints, models.\"}, {\"topic\": \"Flask Routing\", \"question\": \"Describe the process of setting up routing in a Flask app and how you would handle dynamic URLs.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of @app.route, variable rules, request methods, URL building.\"}, {\"topic\": \"MySQL Design & Queries\", \"question\": \"How would you design a MySQL schema for a simple blog application and write a query to fetch posts with their authors?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Normalization, foreign keys, JOINs, SELECT statements.\"}, {\"topic\": \"REST API Development\", \"question\": \"Explain how you would create a RESTful API endpoint in Django or Flask that accepts JSON data and returns a JSON response.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of request.get_json(), jsonify, status codes, CRUD operations.\"}, {\"topic\": \"Front-end Development\", \"question\": \"What steps would you take to ensure a responsive UI using Bootstrap and vanilla JavaScript?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Bootstrap grid, components, media queries, DOM manipulation basics.\"}, {\"topic\": \"Git & GitHub\", \"question\": \"How do you use Git for version control during a team project, and what commands are essential for collaboration?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"git clone, add, commit, push, pull, branch, merge, conflict resolution.\"}]','2026-11-16 07:06:00'),(13,26,'[{\"topic\": \"Python OOP\", \"question\": \"Explain the key concepts of Object-Oriented Programming in Python and give a simple example of a class with attributes and methods.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Definition of class, object, attributes, methods, encapsulation, inheritance, example code showing a class definition and instantiation.\"}, {\"topic\": \"Flask\", \"question\": \"How would you create a simple Flask route that returns the text \\\"Hello, World!\\\" when accessed via a browser?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of @app.route decorator, definition of a view function, returning a string, and running the Flask app.\"}, {\"topic\": \"Python Data Structures\", \"question\": \"What is the difference between a list and a tuple in Python?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Mutability, syntax differences, typical use cases for lists vs tuples, and performance considerations.\"}, {\"topic\": \"MySQL\", \"question\": \"Write a MySQL query to retrieve all records from a table named `employees` where the `department` column equals \'Sales\'.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"SELECT statement, FROM clause, WHERE clause, correct use of string literals and table/column names.\"}, {\"topic\": \"Bootstrap\", \"question\": \"Describe how you would create a responsive navigation bar using Bootstrap 5. What classes and components would you use?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of navbar component, container, navbar-brand, navbar-toggler, collapse, nav-item, nav-link, and responsive breakpoints.\"}, {\"topic\": \"REST API\", \"question\": \"Explain the steps to create a RESTful API endpoint in Flask that accepts JSON data via POST and returns a JSON response. Include how you would parse the incoming data and send back a response.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of @app.route with methods=[\'POST\'], request.get_json(), processing data, jsonify, and returning a response with appropriate status code.\"}]','2026-11-16 10:42:49'),(14,26,'[{\"topic\": \"Python Data Structures\", \"question\": \"What is the difference between a list and a tuple in Python?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Explanation of mutability vs immutability, syntax differences, typical use cases (lists for collections that change, tuples for fixed data), memory usage considerations.\"}, {\"topic\": \"Flask Basics\", \"question\": \"How would you create a simple Flask route that returns \'Hello, World!\'?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Importing Flask, creating an app instance, defining a route with @app.route, returning a string, running the app with app.run() or using a WSGI server.\"}, {\"topic\": \"Front-end Development\", \"question\": \"Explain how you would structure a basic HTML page with Bootstrap to create a responsive navigation bar.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of <nav> element, Bootstrap classes like navbar, navbar-expand, navbar-light/dark, container-fluid, collapse for mobile, and how to add links.\"}, {\"topic\": \"MySQL\", \"question\": \"Write a simple SQL query to retrieve all records from a table named \'users\' where the \'age\' is greater than 25.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"SELECT * FROM users WHERE age > 25; discussion of SELECT, FROM, WHERE clause, comparison operator, and optional ORDER BY.\"}, {\"topic\": \"REST API\", \"question\": \"Describe how you would design a RESTful API endpoint for creating a new user resource. What HTTP method would you use and what status code would you return on success?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Use of POST method, endpoint /users, request body JSON, validation, returning 201 Created or 200 OK, and handling errors.\"}, {\"topic\": \"Git & GitHub\", \"question\": \"How would you use Git to track changes in your project? Explain the basic workflow of committing and pushing changes to GitHub.\", \"related_evidence\": \"\", \"what_to_listen_for\": \"git init, git add, git commit with meaningful messages, git remote add origin, git push, branch management, and pull requests.\"}, {\"topic\": \"Debugging\", \"question\": \"If you were asked to debug a Flask application that is returning a 500 Internal Server Error, what steps would you take to identify and fix the issue?\", \"related_evidence\": \"\", \"what_to_listen_for\": \"Enabling debug mode, checking server logs, inspecting traceback, verifying code syntax, ensuring required modules are imported, checking database connections, and testing endpoints with tools like curl or Postman.\"}]','2026-11-16 13:37:42'),(15,26,'[{\"topic\": \"Python fundamentals\", \"question\": \"Can you explain how you would define a function in Python and what are the key components of a class in object-oriented programming?\", \"related_evidence\": \"Programming Languages: Python, SQL\", \"what_to_listen_for\": \"Definition of a function (def keyword, parameters, return statement), class definition (class keyword, __init__ method, attributes, methods), basic inheritance example.\"}, {\"topic\": \"Flask backend\", \"question\": \"In Flask, how do you set up a route to handle both GET and POST requests, and how would you retrieve form data submitted by a user?\", \"related_evidence\": \"Web & App Development: HTML, CSS, JavaScript, Streamlit, Flask\", \"what_to_listen_for\": \"Use of @app.route decorator with methods=[\'GET\',\'POST\'], request.form to access form data, rendering a template with render_template.\"}, {\"topic\": \"HTML\", \"question\": \"What are the main semantic HTML tags you would use to structure a simple webpage and why are they important?\", \"related_evidence\": \"Web & App Development: HTML, CSS, JavaScript, Streamlit, Flask\", \"what_to_listen_for\": \"Explanation of tags like <header>, <nav>, <main>, <section>, <article>, <footer>, and their role in accessibility and SEO.\"}, {\"topic\": \"CSS\", \"question\": \"How does the CSS box model work and how would you use it to create a centered container with a fixed width?\", \"related_evidence\": \"Web & App Development: HTML, CSS, JavaScript, Streamlit, Flask\", \"what_to_listen_for\": \"Description of content, padding, border, margin, width, height, and use of margin:0 auto; to center a block element.\"}, {\"topic\": \"JavaScript\", \"question\": \"Can you give an example of how to add a click event listener in JavaScript and change the text of a paragraph element when the button is clicked?\", \"related_evidence\": \"Web & App Development: HTML, CSS, JavaScript, Streamlit, Flask\", \"what_to_listen_for\": \"Use of document.getElementById or querySelector, addEventListener(\'click\', ...), and modifying innerText or innerHTML of a target element.\"}, {\"topic\": \"MySQL\", \"question\": \"What are the basic CRUD operations in MySQL and how would you write a simple SELECT query to retrieve all records from a table named \'employees\'?\", \"related_evidence\": \"Databases: MySQL, SQL Server, SQLite, MongoDB (basics)\", \"what_to_listen_for\": \"Explanation of SELECT, INSERT, UPDATE, DELETE, and a SELECT * FROM employees; statement.\"}, {\"topic\": \"Git & GitHub\", \"question\": \"Describe the typical workflow of using Git for version control, including initializing a repository, committing changes, and pushing to GitHub.\", \"related_evidence\": \"LinkedIn | GitHub\", \"what_to_listen_for\": \"Commands like git init, git add, git commit, git push, and the concept of branches and remote repositories.\"}]','2026-11-17 05:54:58'),(16,29,'[{\"topic\": \"Python fundamentals\", \"question\": \"What is a list comprehension in Python and how does it differ from a regular for loop?\", \"related_evidence\": \"Programming Languages: Python, HTML5, CSS\", \"what_to_listen_for\": \"Explanation of list comprehension syntax, use cases, difference from loop\"}, {\"topic\": \"MySQL queries\", \"question\": \"Explain how you would perform a JOIN between two tables in MySQL. What are the different types of JOINs?\", \"related_evidence\": \"Database Management: MySQL\", \"what_to_listen_for\": \"Description of INNER JOIN, LEFT JOIN, RIGHT JOIN, FULL OUTER JOIN and syntax\"}, {\"topic\": \"CSS\", \"question\": \"How would you create a responsive layout using CSS Flexbox? Provide a simple example.\", \"related_evidence\": \"Programming Languages: Python, HTML5, CSS\", \"what_to_listen_for\": \"Explanation of flex container, flex items, flex-direction, justify-content, align-items and a code snippet\"}, {\"topic\": \"Flask\", \"question\": \"What is Flask and how does routing work in a Flask application?\", \"related_evidence\": \"No evidence found\", \"what_to_listen_for\": \"Definition of Flask, concept of routes, use of @app.route decorator and handling requests\"}, {\"topic\": \"REST API\", \"question\": \"What is a RESTful API and what are the common HTTP methods used?\", \"related_evidence\": \"No evidence found\", \"what_to_listen_for\": \"Definition of REST, statelessness, CRUD mapping to GET, POST, PUT/PATCH, DELETE\"}, {\"topic\": \"Git & GitHub\", \"question\": \"What is Git and why is it useful in software development? Explain the difference between \'git pull\' and \'git fetch\'.\", \"related_evidence\": \"No evidence found\", \"what_to_listen_for\": \"Explanation of version control, distributed nature, difference between pull (fetch + merge) and fetch (only download)\"}]','2026-11-17 11:39:05'),(17,29,'[{\"topic\": \"Python Basics\", \"question\": \"What are the main data types in Python and how do you decide which one to use in a given situation?\", \"related_evidence\": \"Python evidence found\", \"what_to_listen_for\": \"Candidate explains int, float, str, list, tuple, dict, set; discusses immutability, mutability, memory usage, and typical use cases.\"}, {\"topic\": \"Python OOP\", \"question\": \"Can you explain how classes and objects work in Python, and give an example of inheritance?\", \"related_evidence\": \"Python evidence found\", \"what_to_listen_for\": \"Candidate describes class definition, __init__, attributes, methods, inheritance, super(), and a simple example such as a base class Vehicle and a subclass Car.\"}, {\"topic\": \"MySQL\", \"question\": \"Write a simple SQL query to retrieve all records from a table named \'employees\' where the department is \'Sales\'. What does the query do?\", \"related_evidence\": \"MySQL evidence found\", \"what_to_listen_for\": \"Candidate writes SELECT * FROM employees WHERE department = \'Sales\'; explains SELECT, FROM, WHERE, filtering.\"}, {\"topic\": \"HTML\", \"question\": \"What is the purpose of the <header>, <nav>, <main>, and <footer> tags in HTML5?\", \"related_evidence\": \"HTML evidence found\", \"what_to_listen_for\": \"Candidate explains semantic tags, accessibility, SEO benefits, and typical content for each section.\"}, {\"topic\": \"CSS\", \"question\": \"Explain the CSS box model and how padding, border, and margin affect element layout.\", \"related_evidence\": \"CSS evidence found\", \"what_to_listen_for\": \"Candidate describes content, padding, border, margin, width/height, and how they combine to determine total element size.\"}, {\"topic\": \"Flask\", \"question\": \"In Flask, how would you set up a route that responds to a GET request at the URL \'/hello\'?\", \"related_evidence\": \"Flask evidence not found\", \"what_to_listen_for\": \"Candidate mentions @app.route(\'/hello\') decorator, defines a function, returns a string or template, and explains HTTP methods.\"}, {\"topic\": \"Git\", \"question\": \"What are the basic steps to initialize a Git repository and push your first commit to GitHub?\", \"related_evidence\": \"Git & GitHub evidence not found\", \"what_to_listen_for\": \"Candidate describes git init, git add, git commit, creating a remote, git push, and the purpose of each command.\"}]','2026-11-17 11:39:29'),(18,27,'[{\"topic\": \"Python Fundamentals\", \"question\": \"What is a Python function and how do you define and call it?\", \"related_evidence\": \"Python (Basics)\", \"what_to_listen_for\": \"Definition of a function, use of def keyword, parameters, return statement, example of calling a function with arguments.\"}, {\"topic\": \"Python Data Structures\", \"question\": \"Explain the difference between a list and a tuple in Python. When would you use each?\", \"related_evidence\": \"Python (Basics)\", \"what_to_listen_for\": \"Mutable vs immutable, syntax differences, use cases such as lists for collections that change, tuples for fixed data, memory efficiency.\"}, {\"topic\": \"Exception Handling\", \"question\": \"How do you handle exceptions in Python? Provide an example of try-except-finally.\", \"related_evidence\": \"Python (Basics)\", \"what_to_listen_for\": \"Purpose of try-except, catching specific exceptions, using finally for cleanup, example code snippet.\"}, {\"topic\": \"File Handling\", \"question\": \"Write a small Python code snippet that reads a text file and prints each line.\", \"related_evidence\": \"Python (Basics)\", \"what_to_listen_for\": \"Use of open(), with statement, iterating over file object, printing lines, handling file not found.\"}, {\"topic\": \"Object-Oriented Programming\", \"question\": \"Describe what OOP is in Python and give an example of a class with an attribute and a method.\", \"related_evidence\": \"Python (Basics)\", \"what_to_listen_for\": \"Definition of OOP, class syntax, __init__ method, instance attributes, instance methods, example class.\"}, {\"topic\": \"Basic Coding Problem\", \"question\": \"Suppose you have a list of numbers and you want to find the sum of all even numbers. Write a Python function to do this.\", \"related_evidence\": \"Python (Basics)\", \"what_to_listen_for\": \"Function definition, loop or list comprehension, conditional check for even numbers, summing, returning result.\"}]','2026-11-19 06:13:18');
