INSERT INTO `vacancies` VALUES (1,'Python Fullstack Developer','Job Title: Python Full Stack Developer\r\nExperience: Fresher / 0–2 Years\r\nEmployment Type: Full-Time\r\nJob Location: Hyderabad, India\r\nJob Summary\r\nWe are looking for a motivated Python Full Stack Developer who is passionate about building web applications and learning new technologies. The candidate should have knowledge of Python programming, front-end development, database management, and backend development using Flask or Django.\r\n\r\nThe ideal candidate should be able to develop user-friendly web applications, write clean and maintainable code, integrate databases, and work with a development team to deliver software solutions.\r\nKey Responsibilities\r\n1. Develop and maintain web applications using Python.\r\n2. Build backend applications using Flask or Django.\r\n3. Design responsive user interfaces using HTML, CSS, JavaScript, and Bootstrap.\r\n4. Create and manage databases using MySQL.\r\n5. Develop REST APIs and integrate third-party APIs.\r\n6. Perform debugging, testing, and troubleshooting.\r\n7. Write clean, reusable, and maintainable code.\r\n8. Collaborate with frontend developers, backend developers, and team members.\r\n9. Understand project requirements and implement new features.\r\n10. Maintain application performance, security, and reliability.\r\nRequired Technical Skills\r\nSkill	Expected Knowledge\r\nPython	Core Python, OOP, Functions\r\nFlask / Django	Backend development\r\nHTML	Web page structure\r\nCSS	Styling and layouts\r\nJavaScript	Basic DOM manipulation\r\nBootstrap	Responsive UI\r\nMySQL	Queries, Joins, CRUD\r\nREST API	API development and integration\r\nGit & GitHub	Version control\r\n\r\nAdditional Skills\r\n- Knowledge of Generative AI and AI API integration.\r\n- Understanding of software development life cycle (SDLC).\r\n- Knowledge of data structures and algorithms.\r\n- Problem-solving and analytical thinking.\r\n- Good communication and teamwork skills.\r\nEducational Qualifications\r\n- B.Tech / B.E. in Computer Science, IT, or related fields.\r\n- Freshers and recent graduates can apply.\r\n- Candidates with practical project experience are preferred.\r\nInterview Preparation Topics\r\nFor a Python Full Stack Developer fresher interview, prepare these topics:\r\n1. Python fundamentals and OOP concepts.\r\n2. Lists, tuples, dictionaries, and sets.\r\n3. Exception handling and file handling.\r\n4. Flask architecture and routing.\r\n5. HTML, CSS, JavaScript, and Bootstrap.\r\n6. MySQL queries, joins, and relationships.\r\n7. REST API concepts.\r\n8. Authentication and authorization.\r\n9. Git and GitHub basics.\r\n10. Explain your real-time projects and development experience.','[\"Python\", \"Flask\", \"HTML\", \"CSS\", \"JavaScript\", \"Bootstrap\", \"MySQL\", \"REST API\", \"Git & GitHub\"]','[\"git\"]','Hyderabad',10,'Open',2,'2026-11-11 08:46:56'),(2,'Zoho Developer','Job Description\r\n\r\nWe are looking for a motivated and enthusiastic Junior Zoho Developer to join our software development team. The candidate will work on Zoho applications, customize CRM modules, develop automation workflows, and create business solutions using Deluge scripting.\r\n\r\nFreshers with good programming fundamentals and an interest in cloud-based business applications are encouraged to apply.\r\n\r\nKey Responsibilities\r\n- Customize Zoho CRM modules, fields, layouts, and forms.\r\n- Develop scripts using Zoho Deluge.\r\n- Create workflows, custom functions, and automation rules.\r\n- Work with Zoho CRM APIs and third-party integrations.\r\n- Develop Client Scripts using JavaScript.\r\n- Debug and troubleshoot application issues.\r\n- Work with senior developers on real-time projects.\r\n  \r\n  Required Skills\r\n- Zoho CRM\r\n- Deluge Scripting\r\n- JavaScript\r\n- HTML\r\n- CSS\r\n- REST APIs\r\n- MySQL\r\n- Problem-solving\r\n- Communication Skills\r\n  \r\n  Preferred Skills\r\n- Zoho Creator\r\n- Zoho Books\r\n- Zoho Flow\r\n- API Integration\r\n- JSON\r\n- Bootstrap\r\n  \r\n  Eligibility Criteria\r\n- Freshers and candidates with up to 1 year of experience can apply.\r\n- Basic knowledge of programming concepts.\r\n- Understanding of CRM concepts is an advantage.\r\n- Good analytical and communication skills.','[\"Required Skills\\r\\nZoho CRM\\r\\nDeluge Scripting\\r\\nJavaScript\\r\\nHTML\\r\\nCSS\\r\\nREST APIs\\r\\nMySQL\\r\\nProblem-solving\\r\\nCommunication Skills\"]','[\"git\"]','bengaluru',5,'Open',2,'2026-11-11 10:44:03'),(3,'Java Full Stack Developer','We are looking for a motivated Java Full Stack Developer to design, develop, and maintain web applications using Java-based backend technologies and modern frontend technologies.\r\nBasic Information\r\nField	Value\r\nJob Title	Java Full Stack Developer\r\nDepartment	Software Development\r\nEmployment Type	Full Time\r\nExperience	0–2 Years\r\nNumber of Vacancies	5\r\nWork Mode	On-site\r\nLocation	Hyderabad\r\nSalary Range	₹3–5 LPA\r\nQualification	B.Tech / B.E / MCA / M.Sc\r\n\r\nRequired Skills\r\n- Java\r\n- Spring Boot\r\n- Hibernate\r\n- MySQL\r\n- HTML, CSS, JavaScript\r\n- React.js or Angular\r\n- REST APIs\r\n- Git and GitHub\r\nResponsibilities\r\n1. Develop frontend and backend application features.\r\n2. Build REST APIs using Spring Boot.\r\n3. Design and manage MySQL databases.\r\n4. Integrate frontend interfaces with backend services.\r\n5. Debug and fix application issues.\r\n6. Work with the development team.\r\nPreferred Skills\r\n- Knowledge of Microservices.\r\n- Basic knowledge of AWS.\r\n- Understanding of Agile methodology.\r\nApplication Deadline: 30 December 2026','[\"Required Skills\\r\\n- Java\\r\\n- Spring Boot\\r\\n- Hibernate\\r\\n- MySQL\\r\\n- HTML\", \"CSS\", \"JavaScript\\r\\n- React.js or Angular\\r\\n- REST APIs\\r\\n- Git and GitHub\"]','[\"Git\"]','Bengaluru',15,'Open',4,'2026-11-17 05:03:27');
